
/* =====================================================================
   FinanceLab: practice database for SQL Server (T-SQL)
   All companies, banks, funds and investors are FICTIONAL.
   Prices and indicators are synthetic, made for practice only.
   Money in statements, bank financials and AUM = INR crore
   (1 crore = 10,000,000). Prices, DPS and loan amounts = INR.
   Run the whole script in SSMS or Azure Data Studio (SQL Server 2016+).
   ===================================================================== */
SET NOCOUNT ON;
GO
IF DB_ID('FinanceLab') IS NULL CREATE DATABASE FinanceLab;
GO
USE FinanceLab;
GO

DROP TABLE IF EXISTS economic_indicators, loans, bank_financials, banks,
    portfolio_transactions, portfolios, fund_holdings, fund_nav, funds,
    dividends, stock_prices, cash_flow_statements, balance_sheets,
    income_statements, companies;
GO

CREATE TABLE companies (
    company_id          INT          PRIMARY KEY,
    ticker              VARCHAR(10)  NOT NULL UNIQUE,
    company_name        VARCHAR(100) NOT NULL,
    sector              VARCHAR(50)  NOT NULL,
    country             VARCHAR(50)  NOT NULL,
    listing_date        DATE         NOT NULL,
    shares_outstanding  BIGINT       NOT NULL
);

CREATE TABLE income_statements (
    company_id          INT           NOT NULL REFERENCES companies(company_id),
    fiscal_year         INT           NOT NULL,
    fiscal_quarter      INT           NOT NULL,
    period_end_date     DATE          NOT NULL,
    revenue             DECIMAL(14,2) NOT NULL,
    cost_of_revenue     DECIMAL(14,2) NOT NULL,
    operating_expenses  DECIMAL(14,2) NOT NULL,
    depreciation        DECIMAL(14,2) NOT NULL,
    interest_expense    DECIMAL(14,2) NOT NULL,
    tax_expense         DECIMAL(14,2) NOT NULL,
    net_income          DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (company_id, fiscal_year, fiscal_quarter)
);

CREATE TABLE balance_sheets (
    company_id            INT           NOT NULL REFERENCES companies(company_id),
    fiscal_year           INT           NOT NULL,
    fiscal_quarter        INT           NOT NULL,
    period_end_date       DATE          NOT NULL,
    total_assets          DECIMAL(14,2) NOT NULL,
    current_assets        DECIMAL(14,2) NOT NULL,
    cash_and_equivalents  DECIMAL(14,2) NOT NULL,
    inventory             DECIMAL(14,2) NOT NULL,
    total_liabilities     DECIMAL(14,2) NOT NULL,
    current_liabilities   DECIMAL(14,2) NOT NULL,
    long_term_debt        DECIMAL(14,2) NOT NULL,
    retained_earnings     DECIMAL(14,2) NOT NULL,
    shareholders_equity   DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (company_id, fiscal_year, fiscal_quarter)
);

CREATE TABLE cash_flow_statements (
    company_id            INT           NOT NULL REFERENCES companies(company_id),
    fiscal_year           INT           NOT NULL,
    fiscal_quarter        INT           NOT NULL,
    period_end_date       DATE          NOT NULL,
    operating_cash_flow   DECIMAL(14,2) NOT NULL,
    capital_expenditure   DECIMAL(14,2) NOT NULL,  -- positive number = cash spent
    investing_cash_flow   DECIMAL(14,2) NOT NULL,
    financing_cash_flow   DECIMAL(14,2) NOT NULL,
    dividends_paid        DECIMAL(14,2) NOT NULL,  -- positive number = cash paid out
    PRIMARY KEY (company_id, fiscal_year, fiscal_quarter)
);

CREATE TABLE stock_prices (
    company_id   INT           NOT NULL REFERENCES companies(company_id),
    trade_date   DATE          NOT NULL,
    open_price   DECIMAL(12,2) NOT NULL,
    high_price   DECIMAL(12,2) NOT NULL,
    low_price    DECIMAL(12,2) NOT NULL,
    close_price  DECIMAL(12,2) NOT NULL,
    volume       BIGINT        NOT NULL,
    PRIMARY KEY (company_id, trade_date)
);

CREATE TABLE dividends (
    dividend_id         INT          PRIMARY KEY,
    company_id          INT          NOT NULL REFERENCES companies(company_id),
    ex_dividend_date    DATE         NOT NULL,
    record_date         DATE         NOT NULL,
    payment_date        DATE         NOT NULL,
    dividend_per_share  DECIMAL(8,2) NOT NULL,
    dividend_type       VARCHAR(10)  NOT NULL   -- 'Regular' or 'Special'
);

CREATE TABLE funds (
    fund_id         INT          PRIMARY KEY,
    fund_name       VARCHAR(100) NOT NULL,
    fund_type       VARCHAR(20)  NOT NULL,      -- 'Mutual Fund' or 'ETF'
    category        VARCHAR(30)  NOT NULL,      -- Large Cap, Mid Cap, Index, Sector, Debt
    fund_house      VARCHAR(60)  NOT NULL,
    expense_ratio   DECIMAL(5,2) NOT NULL,      -- % per year
    inception_date  DATE         NOT NULL
);

CREATE TABLE fund_nav (
    fund_id     INT           NOT NULL REFERENCES funds(fund_id),
    nav_date    DATE          NOT NULL,         -- month-end
    nav         DECIMAL(12,4) NOT NULL,
    aum_crore   DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (fund_id, nav_date)
);

CREATE TABLE fund_holdings (
    fund_id     INT          NOT NULL REFERENCES funds(fund_id),
    company_id  INT          NOT NULL REFERENCES companies(company_id),
    as_of_date  DATE         NOT NULL,
    weight_pct  DECIMAL(6,2) NOT NULL,
    PRIMARY KEY (fund_id, company_id, as_of_date)
);

CREATE TABLE portfolios (
    portfolio_id       INT          PRIMARY KEY,
    investor_name      VARCHAR(80)  NOT NULL,
    risk_profile       VARCHAR(20)  NOT NULL,
    start_date         DATE         NOT NULL,
    benchmark_fund_id  INT          NOT NULL REFERENCES funds(fund_id)
);

CREATE TABLE portfolio_transactions (
    transaction_id    INT           PRIMARY KEY,
    portfolio_id      INT           NOT NULL REFERENCES portfolios(portfolio_id),
    company_id        INT           NOT NULL REFERENCES companies(company_id),
    transaction_date  DATE          NOT NULL,
    transaction_type  VARCHAR(4)    NOT NULL,   -- 'BUY' or 'SELL'
    quantity          INT           NOT NULL,
    price             DECIMAL(12,2) NOT NULL,
    brokerage_fee     DECIMAL(10,2) NOT NULL
);

CREATE TABLE banks (
    bank_id           INT          PRIMARY KEY,
    bank_name         VARCHAR(100) NOT NULL,
    bank_type         VARCHAR(20)  NOT NULL,    -- Public, Private, Foreign, Small Finance
    headquarters_city VARCHAR(50)  NOT NULL,
    established_year  INT          NOT NULL
);

CREATE TABLE bank_financials (
    bank_id              INT           NOT NULL REFERENCES banks(bank_id),
    fiscal_year          INT           NOT NULL,
    total_deposits       DECIMAL(14,2) NOT NULL,
    total_advances       DECIMAL(14,2) NOT NULL,
    gross_npa            DECIMAL(14,2) NOT NULL,
    net_npa              DECIMAL(14,2) NOT NULL,
    net_interest_income  DECIMAL(14,2) NOT NULL,
    operating_profit     DECIMAL(14,2) NOT NULL,
    provisions           DECIMAL(14,2) NOT NULL,
    net_profit           DECIMAL(14,2) NOT NULL,
    tier1_capital        DECIMAL(14,2) NOT NULL,
    risk_weighted_assets DECIMAL(14,2) NOT NULL,
    PRIMARY KEY (bank_id, fiscal_year)
);

CREATE TABLE loans (
    loan_id             INT           PRIMARY KEY,
    bank_id             INT           NOT NULL REFERENCES banks(bank_id),
    borrower_segment    VARCHAR(20)   NOT NULL,  -- Retail, MSME, Corporate, Agriculture
    loan_type           VARCHAR(30)   NOT NULL,
    principal_amount    DECIMAL(14,2) NOT NULL,  -- INR
    outstanding_amount  DECIMAL(14,2) NOT NULL,  -- INR
    interest_rate       DECIMAL(5,2)  NOT NULL,  -- % per year
    tenure_months       INT           NOT NULL,
    disbursement_date   DATE          NOT NULL,
    loan_status         VARCHAR(20)   NOT NULL,  -- Active, Closed, Default, Restructured
    days_past_due       INT           NOT NULL
);

CREATE TABLE economic_indicators (
    indicator_month       DATE         NOT NULL,  -- first day of month
    country               VARCHAR(50)  NOT NULL,
    cpi_inflation_pct     DECIMAL(6,2) NOT NULL,
    policy_rate_pct       DECIMAL(6,2) NOT NULL,
    gdp_growth_pct        DECIMAL(6,2) NULL,      -- only filled in quarter-end months
    unemployment_pct      DECIMAL(6,2) NOT NULL,
    bond_yield_10y_pct    DECIMAL(6,2) NOT NULL,
    currency_per_usd      DECIMAL(10,4) NOT NULL,
    PRIMARY KEY (indicator_month, country)
);
GO

